export type GlyphFont = keyof typeof GLYPHS;

const sets = Object.fromEntries(Object.entries(GLYPHS).map(([k, v]) => [k, new Set(v)])) as Record<GlyphFont, Set<string>>;

// Characters in text that the font cannot draw (whitespace and newlines are fine).
export function missingGlyphs(text: string, font: GlyphFont): string[] {
  const set = sets[font];
  const missing = new Set<string>();
  for (const ch of text) if (!/\s/.test(ch) && !set.has(ch)) missing.add(ch);
  return [...missing];
}
